import React from 'react';
import TaskCard from './TaskCard';

const TaskBoard = ({ tasks, onTaskUpdate, currentUser }) => {
  const columns = [
    { id: 'todo', title: '📋 To Do', color: 'bg-gray-100', count: tasks.filter(t => t.status === 'todo').length },
    { id: 'in_progress', title: '🚧 In Progress', color: 'bg-blue-100', count: tasks.filter(t => t.status === 'in_progress').length },
    { id: 'done', title: '✅ Done', color: 'bg-green-100', count: tasks.filter(t => t.status === 'done').length }
  ];

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = (e, newStatus) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    if (taskId && onTaskUpdate) {
      onTaskUpdate(taskId, newStatus);
    }
  };

  return (
    <div className="task-board">
      <div className="board-header">
        <h2>Task Board</h2>
        <div className="board-stats">
          Total Tasks: {tasks.length}
        </div>
      </div>
      
      <div className="columns-container">
        {columns.map(column => (
          <div 
            key={column.id}
            className={`task-column ${column.color}`}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, column.id)}
          >
            <div className="column-header">
              <h3>{column.title}</h3>
              <span className="task-count">{column.count}</span>
            </div>
            <div className="tasks-list">
              {tasks
                .filter(task => task.status === column.id)
                .map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    onStatusChange={onTaskUpdate}
                    currentUser={currentUser}
                  />
                ))
              }
              {tasks.filter(task => task.status === column.id).length === 0 && (
                <div className="empty-column">
                  No tasks in {column.title.toLowerCase()}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TaskBoard;
